'use strict';
const {clues,suspects,rules,fresh,available,collect,connect,accuse}=Mystery;
let difficulty='easy',selectedDifficulty='easy';let menuPaused=false;let demoSession=null,demoIndex=0,targetObject=null;let scenePositions={},pointerStart=null;let state=fresh(),started=false,focusedObject='desk',panel='',soundOn=false,audioContext=null,toastTimer=null,lastFocus=null,playTimer=null,timeConsole=true,elapsed=0,playbackWanted=false;
const $=id=>document.getElementById(id), times=['10:03 PM','10:06 PM','10:09 PM','10:12 PM'];
const objects=[{id:'window',label:'Latched window',x:17,y:29},{id:'door',label:'Locked door',x:2.5,y:53},{id:'clock',label:'Wall clock',x:39,y:18},{id:'shelf',label:'Bookshelf',x:60,y:38},{id:'desk',label:'Desk & ribbon',x:35,y:68},{id:'key',label:'Silver key',x:46,y:70},{id:'receipt',label:'Receipt',x:49,y:64},{id:'body',label:'Dr. Adrian Vale',x:52,y:83},{id:'fireplace',label:'Burned document',x:84,y:57},{id:'ledger',label:'Charred ledger',x:94,y:70},{id:'trail',label:'Shadow trail',x:61,y:73}];
function tone(freq=440){if(!soundOn)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;o.connect(g);g.connect(audioContext.destination);g.gain.setValueAtTime(.035,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.4);o.start();o.stop(audioContext.currentTime+.4);}catch{soundOn=false;}}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function show(title,html,wide=false){if(!$('modal').open)lastFocus=document.activeElement;Scene3D.pause(true);document.body.classList.add('scene-paused');panel=title;$('modalEyebrow').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.toggle('wide',wide);if(!$('modal').open)$('modal').showModal();$('closeModal').focus();syncOfficeMusic();requestAnimationFrame(()=>document.querySelectorAll('canvas[data-portrait]').forEach(c=>Scene3D.portrait(c,c.dataset.portrait)));}
function close(){if($('modal').open)$('modal').close();panel='';Scene3D.pause(false);document.body.classList.remove('scene-paused');if(lastFocus&&document.contains(lastFocus))lastFocus.focus();if(demoSession?.phase==='briefing')deployTraining();else if(demoSession?.phase==='complete'&&!demoSession.debriefSeen)trainingDebrief();syncOfficeMusic();}
function render(){$('difficultyBadge').textContent=demoSession?'TRAINING':difficulty.toUpperCase();updateGuidance();saveProgress();syncMenuVideo();syncOfficeMusic();$('cameraView').textContent=Scene3D.position().view==='third'?'Third person':'First person';
$('evidenceCount').textContent=`${state.evidence.length} / ${Object.keys(clues).length}`;
$('roomMode').textContent=`${state.mode==='normal'?'TIME':state.mode.toUpperCase()} / ${times[state.time]}`;
document.querySelector('.room-shell').className=`room-shell mode-${state.mode}`;
$('shadowAbility').classList.toggle('active',state.mode==='shadow');$('shadowAbility').setAttribute('aria-pressed',state.mode==='shadow');$('fireAbility').classList.toggle('active',state.mode==='fire');$('fireAbility').setAttribute('aria-pressed',state.mode==='fire');
$('timeStops').innerHTML=times.map((t,i)=>`<button data-time="${i}" aria-label="Reconstruct ${t}" aria-pressed="${i===state.time}" class="${i===state.time?'active':''}">${t}</button>`).join('');
Scene3D.setState(state);Scene3D.setActive(!$('game').hidden);
$('sceneStatus').textContent=['10:03 — Vale is alive. The silver key rests on the desk.','10:06 — A visitor approaches. The silver key changes hands.','10:09 — Vale falls. The visitor advances the clock to 10:12.','10:12 — An empty room. A stopped clock. A missing key.'][state.time];
$('hotspots').innerHTML=objects.filter(o=>o.id!=='trail'||(state.mode==='shadow'&&state.time===2)).map(o=>{let x=o.x,y=o.y;if(o.id==='body'&&state.time<2){x=46;y=55}if(o.id==='key'&&state.time===1){x=53.5;y=64}const id=available(state,o.id);return `<button class="hotspot ${id&&state.evidence.includes(id)?'known':''} ${o.id==='trail'?'special':''}" style="left:${x}%;top:${y}%" data-object="${o.id}" aria-label="Inspect ${o.label}"><span class="label">${o.label} · E</span></button>`}).join('');
$('progress').textContent=state.ending==='solved'?'CASE CLOSED':`${state.deductions.length} / 3 DEDUCTIONS ESTABLISHED`;
$('powerReadout').textContent=state.mode==='shadow'?'SHADOW SCANNER // ACTIVE':state.mode==='fire'?'THERMAL RECOVERY // ACTIVE':'NORMAL VISION';$('powerReadout').className='power-readout '+state.mode;
$('objectStrip').innerHTML=objects.filter(o=>o.id!=='trail'||(state.mode==='shadow'&&state.time===2)).map(o=>`<button data-object="${o.id}">${available(state,o.id)&&state.evidence.includes(available(state,o.id))?'✓ ':''}${o.label}</button>`).join('');
$('timeAbility').classList.toggle('active',timeConsole);$('timeAbility').setAttribute('aria-pressed',timeConsole);$('timeline').hidden=!timeConsole;updateTransport();
$('objective').textContent=state.deductions.length===3?'Your theory is ready. Review the evidence and name the killer.':'The room remembers. Look closer.';
}
function setTime(i){if(!Number.isInteger(i)||i<0||i>3)return;state.time=i;elapsed=0;render();$('scene').classList.remove('rewind');void $('scene').offsetWidth;$('scene').classList.add('rewind');tone(220+i*70);}
function mode(m){if($('modal').open)return;state.mode=state.mode===m?'normal':m;render();tone(m==='shadow'?220:330);toast(state.mode==='normal'?'Normal vision restored.':`${m==='shadow'?'SHADOW — Examine the shelf and trail at 10:06–10:09.':'FIRE — Inspect the ash and ledger at 10:12.'}`);}
const ordinary={
 window:['Latched window','Rain taps the glass. The inner sill has not been touched.'],door:['The locked office','The bolt is still drawn from inside. The small silver key is not the door key.'],desk:['The writing desk','A ribbon lies among Vale’s notes. The drawer is open, but nothing has been forced.'],key:['The silver key',()=>state.time===0?'The silver key rests beside Vale’s papers. Reconstruct 10:06 to discover what happens to it.':state.time>=2?'The key is gone. Rewind to 10:06 and inspect its movement.':'The visitor reaches for the silver key.'],clock:['The wall clock',()=>state.time===3?'Stopped at 10:12. Is the displayed time reliable? Reconstruct 10:09 and inspect the clock.':'The pendulum moves in the echo. Inspect this clock at 10:09 to examine the critical change.'],shelf:['A wall of books','The shelf feels deeper than it should. SHADOW may reveal its construction at 10:06 or 10:09.'],body:['Dr. Adrian Vale','Vale is alive in this moment, writing at his desk. Reconstruct 10:09 or later to examine the aftermath.'],fireplace:['Ash in the grate',()=>state.time===3?'Someone burned a document. Use FIRE, then inspect the grate to recover its words.':'The incriminating document has not yet been burned. Examine the aftermath at 10:12 using FIRE.'],ledger:['The charred ledger',()=>state.time===3?'A maintenance ledger is scorched at the edges. FIRE can reveal its erased pressure marks.':'The ledger is not yet charred in this echo. Return to 10:12 and use FIRE.'],receipt:['A collector’s receipt','A signed receipt lies beside the papers.'],trail:['A concealed route','This trail is visible only in SHADOW at 10:09.']};
function inspect(obj){focusedObject=obj;targetObject=obj;const id=available(state,obj);if(id){const c=clues[id],owned=state.evidence.includes(id);show('OBJECT INSPECTION',`<div class="inspection-visual">${GameArt.svg(obj)}</div><span class="badge ${c.type}">${c.type} EVIDENCE · ${times[state.time]}</span><h2>${c.title}</h2><p>${c.text}</p><div class="panel-actions"><button class="primary" data-collect="${id}" ${owned?'disabled':''}>${owned?'✓ Evidence collected':'Collect evidence'}</button><button class="secondary" data-action="close">${demoSession?'Continue demo':'Return to room'}</button></div>`);}else{const [title,text]=ordinary[obj];show('OBJECT INSPECTION',`<div class="inspection-visual">${GameArt.svg(obj)}</div><h2>${title}</h2><p>${typeof text==='function'?text():text}</p>${demoSession||difficulty!=='easy'?'<button class="primary" data-action="close">Return to investigation</button>':obj==='clock'||obj==='key'?'<button class="primary" data-jump="'+(obj==='clock'?2:1)+'">Reconstruct relevant moment </button>':obj==='shelf'||obj==='trail'?'<button class="primary" data-scan="shadow">Scan at 10:09 </button>':obj==='fireplace'||obj==='ledger'?'<button class="primary" data-scan="fire">Recover at 10:12 </button>':'<button class="primary" data-action="close">Continue investigating </button>'}`);}}
function board(){state.selected=[];renderBoard();}
function renderBoard(message=''){const connected=new Set(rules.filter(r=>state.deductions.includes(r.id)).flatMap(r=>r.needs));show('EVIDENCE / CONNECTIONS',`<h2>Make the room confess.</h2><p>Select two evidence cards to establish a connection. Each card shows its complete report. You can deselect a card or replace the oldest selection.</p><div class="cards evidence-cork">${state.evidence.map(id=>`<button class="clue-card ${state.selected.includes(id)?'selected':''} ${connected.has(id)?'connected':''}" data-select="${id}" aria-pressed="${state.selected.includes(id)}"><div class="evidence-visual">${GameArt.svg(GameArt.clue(id))}</div><span class="badge ${clues[id].type}">${clues[id].type}</span><h3>${clues[id].title}</h3><p class="clue-report">${clues[id].text}</p><small>${state.selected.includes(id)?'● SELECTED':'SELECT CLUE'}</small></button>`).join('')}</div>${state.evidence.length?'':'<div class="empty">Your evidence board is empty. Inspect objects in the office and collect evidence.</div>'}<div class="case-links">${rules.filter(r=>state.deductions.includes(r.id)).map(r=>`<div class="case-thread"><span>${clues[r.needs[0]].title}</span><i></i><span>${clues[r.needs[1]].title}</span><small>${r.title}</small></div>`).join('')}</div><div class="board-controls"><button class="primary" data-action="connect" ${state.selected.length!==2?'disabled':''}>Connect selected (${state.selected.length}/2)</button><button class="secondary" data-action="read" ${state.selected.length!==1?'disabled':''}>Read selected</button><button class="secondary" data-action="theory">Review deductions (${state.deductions.length}/3)</button></div><p role="status" style="color:var(--cyan);margin:12px 0 0">${message}</p>`,true);}
function theory(){show('SUPPORTED DEDUCTIONS',`<h2>A theory built on evidence.</h2>${rules.map(r=>state.deductions.includes(r.id)?`<div class="deduction"><h3>✓ ${r.title}</h3><p>${r.text}</p><button data-remove="${r.id}">Remove connection</button></div>`:`<div class="deduction"><h3>Unresolved: ${r.id==='when'?'When did the murder happen?':r.id==='route'?'How was the locked office left?':'Whose movement contradicts an alibi?'}</h3><p>Connect two relevant collected clues on the evidence board.</p></div>`).join('')}<div class="panel-actions"><button class="primary" data-action="accuse">Review accusation </button><button class="secondary" data-action="board">Evidence board</button></div>`);}
function suspectPanel(final=false){show(final?'FINAL THEORY':'PERSONS OF INTEREST',`<h2>${final?'Who killed Dr. Vale?':'Three stories. One lie.'}</h2><p>${final?(state.deductions.length===3?'You have established the time, the escape route, and the false alibi. Choose a suspect to present your accusation.':`Establish all three deductions before making an accusation. You have ${state.deductions.length}/3. Return to the evidence board to support your theory.`):'Compare their motives and alibis against the evidence. Motive alone cannot prove murder.'}</p><div class="cards">${suspects.map(s=>`<article class="suspect-card"><canvas class="operator-portrait" data-portrait="${s.id}" aria-label="${s.name} portrait"></canvas><div class="eyebrow">${s.role}</div><h3>${s.name}</h3><p><strong>Motive</strong><br>${s.motive}</p><p><strong>Stated alibi</strong><br>${s.alibi}</p><p><strong>Opportunity</strong><br>${s.opportunity}</p><p><strong>Collected evidence</strong><br>${s.links.filter(id=>state.evidence.includes(id)).map(id=>clues[id].title).join(' · ')||'No relevant evidence collected yet.'}</p>${final?`<button data-accuse="${s.id}" ${state.deductions.length<3?'disabled':''}>Accuse ${s.name.split(' ').slice(-1)[0]} </button>`:''}</article>`).join('')}</div><div class="panel-actions"><button class="secondary" data-action="board">Open evidence board</button><button class="secondary" data-action="close">Return to investigation</button></div>`,true);}
function accusation(id){const result=accuse(state,id);render();if(result==='incomplete'){toast('Your accusation needs all three deductions.');return;}if(result==='incorrect'){show('THEORY REJECTED',`<span class="badge">THE CASE REMAINS OPEN</span><h2>A motive is not a movement.</h2><p>${id==='voss'?'Voss’s ribbon was a gift from yesterday. It does not place her at the desk during the ninth minute.':'Thorn’s receipt records an earlier meeting, and the lobby stamp supports his departure before the murder.'} Your theory does not account for the damaged heel and the west-stair ledger. Review those two clues together.</p><div class="panel-actions"><button class="primary" data-action="return">Return to investigation </button><button class="secondary" data-action="restart">Restart case</button></div>`);return;}tone(660);show('CASE 009 / SOLVED',`<span class="badge">TIME · SHADOW · FIRE</span><h2>The room was locked.<br>The story was not.</h2><p>Mara Rook killed Dr. Adrian Vale. His discovery of her falsified invoices threatened her livelihood. The evidence reconstructs her route and exposes her false alibi.</p><div class="reveal-step"><span>01</span><p><strong>10:03 — The key is waiting.</strong>Vale is alive. The silver key on his desk opens the split-ring service latch, not the main door.</p></div><div class="reveal-step"><span>02</span><p><strong>10:06 — The visitor borrows a way out.</strong>Rook has used the west stair despite claiming to be in the boiler room. The temporal echo shows the visitor lifting the key.</p></div><div class="reveal-step"><span>03</span><p><strong>10:09 — The fatal ninth minute.</strong>Vale falls from a close-range attack consistent with the missing letter opener. The visitor moves the clock forward to 10:12 and stops it. TIME exposes the false time of death.</p></div><div class="reveal-step"><span>04</span><p><strong>A broken heel crosses the shadows.</strong>SHADOW traces the route from desk to hidden bookshelf passage. The damaged left heel matches Rook’s repair note and the west-stair record contradicts her alibi.</p></div><div class="reveal-step"><span>05</span><p><strong>10:12 — Fire cannot keep a secret.</strong>The escape instruction and erased ledger survive in ash. FIRE ties the ninth minute to the silver key and service latch. Rook leaves by the west passage with the key; the inside bolt stays drawn and the window remains untouched.</p></div><p>The ribbon and receipt belong to earlier visits. Neither explains the critical movement.</p><div class="panel-actions"><button class="primary" data-action="restart">Rewind the case </button><button class="secondary" data-action="close">Explore the solved room</button></div>`,true);}
function how(){show('HOW TO PLAY',`<h2>Three powers. One truth.</h2><p><strong>Camera:</strong> WASD walks around the 3D office. Drag to look; arrow keys can move forward/back and turn. Hold Shift to run, Space to jump. Switch between third-person and first-person views. On touchscreens, hold the directional buttons and drag the room to look. Reset position returns you to the entrance. This is an investigation, with no shooting controls.</p><p><strong>Inspect:</strong> Approach an object, face it and press E or Inspect nearby. You can also click a visible object or choose Inspect room for an accessible list. Show objective guides you to a clue automatically. Tab and Enter work throughout the menus. Collect evidence in the inspection panel.</p><p><strong>TIME · T:</strong> Press T to open or close the time console. Select a timestamp, step backward/forward, or play the reconstruction. Playback stops at the final moment. Watch the key, visitor, victim and clock change.</p><p><strong>SHADOW · Q:</strong> Reveal hidden movement and the shelf’s concealed passage. Look around 10:06–10:09.</p><p><strong>FIRE · F:</strong> Recover the burned document and ledger at 10:12. Your power restores information without destroying evidence.</p><p><strong>Evidence · B:</strong> Select two related clues and connect them. Establish when, how, and who, then submit your accusation. Evidence persists while you change time or powers.</p><p><strong>Esc:</strong> Close a panel or pause. On touchscreens, all controls are available as buttons.</p><button class="primary" data-action="close">Understood </button>`);}
function settings(){show('SETTINGS',`<h2>Set the atmosphere.</h2><div class="settings-row"><label for="soundSetting">Sound effects & office soundtrack</label><input type="checkbox" id="soundSetting" ${soundOn?'checked':''}></div><div class="settings-row"><label for="motionSetting">Reduce motion</label><input type="checkbox" id="motionSetting" ${document.body.classList.contains('reduced')?'checked':''}></div><p style="margin-top:20px">No essential information relies on sound, animation, or color alone. Your case is saved automatically on this browser.</p>`);}
function toggleSound(){soundOn=!soundOn;$('sound').innerHTML=`♪ <span>Sound ${soundOn?'on':'off'}</span>`;$('sound').setAttribute('aria-label',`${soundOn?'Disable':'Enable'} sound`);tone();syncOfficeMusic();}
function pause(){show('INVESTIGATION PAUSED',`<h2>Take a breath, detective.</h2><p>Your evidence and deductions are preserved. The reconstruction waits for you.</p><div class="panel-actions"><button class="primary" data-action="close">Resume </button><button class="secondary" data-action="how">Controls</button><button class="secondary" data-action="settings">Settings</button><button class="secondary" data-action="restart">Restart case</button><button class="secondary" data-action="title">Title screen</button></div>`);}
function begin(){$('levelScreen').hidden=true;started=true;$('titleScreen').hidden=true;$('game').hidden=false;render();show('OCTOBER 17 / VALE ESTATE',`<span class="badge">THE NINTH MINUTE</span><h2>You arrive three minutes<br>after the truth.</h2><p>Rain settles over Vale Estate. Inside a bolted office, Dr. Adrian Vale lies dead beside his desk. The wall clock reads 10:12. His silver key is missing.</p><p>But you can hear what this room remembers. Reconstruct its last moments. Follow what hides in shadow. Read what the fire tried to erase.</p><p>${difficulty==='easy'?'Begin with the stopped clock. Then rewind.':'Walk the office and reconstruct what happened.'}</p><div class="panel-actions"><button class="primary" data-action="demo">Learn with the guided demo</button><button class="secondary" data-action="close">Enter the office / Skip intro</button></div>`);}
function restartPrompt(){show('RESTART INVESTIGATION',`<h2>Return to the beginning?</h2><p>This clears all collected clues, connections, powers, timeline changes and endings for this run.</p><div class="panel-actions"><button class="primary" data-action="reset">Restart case</button><button class="secondary" data-action="close">Keep investigating</button></div>`);}
function reset(){if(demoSession){exitDemo();return;}targetObject=null;stopPlayback();Scene3D.reset();timeConsole=true;state=fresh();$('cameraView').textContent='First person';focusedObject='desk';started=true;clearTimeout(toastTimer);$('toast').classList.remove('show');$('hintText').textContent='Inspect the room. Rewind the moments before the murder. Some truths only appear in shadow or ash.';$('titleScreen').hidden=true;$('game').hidden=false;close();render();toast('Case reset. Every minute is yours again.');}
function hint(){if(!demoSession&&difficulty==='hard'){toast('Hard mode: use your observations and evidence.');return;}if(!demoSession&&difficulty==='medium'){$('hintText').textContent=state.evidence.length<4?'Compare the room across different moments. Small objects can reveal contradictions.':state.evidence.length<8?'Look for movement with SHADOW and lost information with FIRE.':state.deductions.length<3?'Pair clues that explain a time, an escape route, or a suspect’s access.':'Your deductions are ready. Review the alibis.';return;}const steps=[['key','Reconstruct 10:06 and inspect the silver key in the visitor’s hand.'],['clock','At 10:09, inspect the wall clock. Compare its hands with the temporal reconstruction.'],['passage','Use SHADOW at 10:06 or 10:09 and inspect the bookshelf.'],['trail','Use SHADOW at 10:09. Look for the violet footprints on the floor by the bookshelf.'],['fire','Return to 10:12. Use FIRE and inspect the burned document in the fireplace.'],['roster','Keep FIRE active at 10:12. Inspect the charred ledger to the right of the fireplace.']];const next=steps.find(([id])=>!state.evidence.includes(id));$('hintText').textContent=next?next[1]:state.deductions.length<3?'Connect the borrowed key with the false clock; the service passage with the burned instruction; and the heel trail with the ledger.':'Your three deductions are complete. Review the suspects’ alibis and submit your final theory.';}
$('start').onclick=openLevels;$('how').onclick=how;$('settings').onclick=settings;$('credits').onclick=()=>show('CREDITS',`<h2>Rewind the Murder</h2><p>A playable adaptation of the supplied module-wise game plan. Original perspective-rendered 3D office, block-style portraits, scanner effects and synthesized sound cues. Built with HTML, CSS and JavaScript, without external asset or service dependencies.</p><p>Themes: TIME · SHADOW · FIRE<br>Chapter I: The Ninth Minute</p>`);
$('brand').onclick=e=>{e.preventDefault();if(started)pause();};$('sound').onclick=toggleSound;$('pause').onclick=()=>started?pause():settings();$('closeModal').onclick=close;$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});$('timeAbility').onclick=toggleTimeConsole;$('shadowAbility').onclick=()=>mode('shadow');$('fireAbility').onclick=()=>mode('fire');$('board').onclick=board;$('suspects').onclick=()=>suspectPanel();$('accuse').onclick=()=>suspectPanel(true);$('hint').onclick=hint;
$('timeStops').onclick=e=>{const b=e.target.closest('[data-time]');if(b)setTime(Number(b.dataset.time));};$('objectStrip').onclick=e=>{const b=e.target.closest('[data-object]');if(b)inspect(b.dataset.object);};$('hotspots').onclick=e=>{const b=e.target.closest('[data-object]');if(b)inspect(b.dataset.object);};$('hotspots').addEventListener('focusin',e=>{const b=e.target.closest('[data-object]');if(b)focusedObject=b.dataset.object;});$('hotspots').addEventListener('pointerover',e=>{const b=e.target.closest('[data-object]');if(b)focusedObject=b.dataset.object;});
$('modalBody').addEventListener('change',e=>{if(e.target.id==='soundSetting')toggleSound();if(e.target.id==='motionSetting'){document.body.classList.toggle('reduced',e.target.checked);syncMenuVideo();}});
$('modalBody').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.inspect){inspect(b.dataset.inspect);return;}if(b.dataset.jump!==undefined){close();timeConsole=true;setTime(Number(b.dataset.jump));return;}if(b.dataset.scan){const m=b.dataset.scan;close();state.mode=m;timeConsole=true;setTime(m==='shadow'?2:3);toast('Scanner ready. Inspect the object again to collect its evidence.');return;}if(b.dataset.collect){if(available(state,focusedObject)===b.dataset.collect&&collect(state,b.dataset.collect)){tone(550);toast('Evidence collected: '+clues[b.dataset.collect].title);render();inspect(focusedObject);}return;}if(b.dataset.select){const id=b.dataset.select;if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<2)state.selected.push(id);else state.selected=[state.selected[1],id];renderBoard();return;}if(b.dataset.remove){state.deductions=state.deductions.filter(x=>x!==b.dataset.remove);state.ending=null;render();theory();return;}if(b.dataset.accuse){accusation(b.dataset.accuse);return;}switch(b.dataset.action){case'deploy-training':close();break;case'exit-training':exitDemo();break;case'training-results':trainingDebrief();break;case'close':close();break;case'connect':{const rule=connect(state,state.selected);state.selected=[];render();renderBoard(rule?`Connection established: ${rule.title}.`:'These clues do not establish a shared conclusion. Look for a time contradiction, a matching route, or a physical mark supported by a record.');if(rule)tone(660);break;}case'read':{const c=clues[state.selected[0]];if(c)show('COLLECTED EVIDENCE',`<span class="badge ${c.type}">${c.type}</span><h2>${c.title}</h2><p>${c.text}</p><button class="primary" data-action="board">Back to board </button>`);break;}case'demo':startDemo();break;case'board':board();break;case'theory':theory();break;case'accuse':suspectPanel(true);break;case'return':state.ending=null;close();render();break;case'restart':restartPrompt();break;case'reset':reset();break;case'how':how();break;case'settings':settings();break;case'title':if(demoSession)exitDemo();stopPlayback();close();Scene3D.setActive(false);$('game').hidden=true;$('titleScreen').hidden=false;syncMenuVideo();syncOfficeMusic();$('start').textContent='▶ PLAY';$('start').onclick=openLevels;break;}};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;const key=e.key.toLowerCase();if($('modal').open)return;if($('game').hidden)return;if(['t','q','f','e','b','escape'].includes(key))e.preventDefault();if(key==='t')toggleTimeConsole();if(key==='q')mode('shadow');if(key==='f')mode('fire');if(key==='e')inspectNearby();if(key==='b')board();if(key==='escape')pause();});
const learningSteps=[
 {obj:'door',clue:'door',time:3,mode:'normal',title:'01 · Inspect the locked door',text:'Start with one object. Click the door label, read the report, then press Collect evidence. This proves the main door was locked from inside.',button:'Find the door'},
 {obj:'key',clue:'key',time:1,mode:'normal',title:'02 · Rewind with TIME',text:'TIME shows an earlier version of the room. At 10:06, the visitor takes the silver key. Inspect it and collect its report.',button:'Rewind to 10:06'},
 {obj:'clock',clue:'clock',time:2,mode:'normal',title:'03 · Compare the clock',text:'Reconstruct 10:09. The wall clock says 10:12, but the reconstruction says 10:09. Inspect the clock and collect the contradiction.',button:'Focus the clock'},
 {obj:'trail',clue:'trail',time:2,mode:'shadow',title:'04 · Follow the shadow',text:'SHADOW reveals movement hidden from normal sight. At 10:09, inspect the violet footprint trail and collect it.',button:'Activate SHADOW'},
 {obj:'shelf',clue:'passage',time:2,mode:'shadow',title:'05 · Find the hidden route',text:'Keep SHADOW active. Inspect the bookshelf to discover a concealed service passage. Collect the passage report.',button:'Focus the bookshelf'},
 {obj:'fireplace',clue:'fire',time:3,mode:'fire',title:'06 · Recover the burned note',text:'FIRE restores information; it does not damage the room. At 10:12, inspect the paper in the fireplace and collect the recovered message.',button:'Activate FIRE'},
 {obj:'ledger',clue:'roster',time:3,mode:'fire',title:'07 · Read the damaged ledger',text:'With FIRE active, inspect the charred ledger beside the fireplace. Collect the recovered access record.',button:'Focus the ledger'},
 {rule:'when',title:'08 · Make your first connection',text:'Open Evidence. Select The borrowed key and Nine minutes, not twelve, then press Connect selected. Together they establish the true murder time.',button:'Open evidence board'}
];
function currentGoal(){if(demoSession)return demoSession.phase==='movement'||demoSession.phase==='briefing'?null:learningSteps[demoIndex]||null;return learningSteps.find(step=>step.clue?!state.evidence.includes(step.clue):!state.deductions.includes(step.rule))||null;}
function updateGuidance(){const guided=!!demoSession||difficulty==='easy';$('focusGoal').hidden=!guided;$('hint').hidden=!demoSession&&difficulty==='hard';
 const previousDemoIndex=demoIndex;if(demoSession&&demoSession.phase==='investigation'){while(demoIndex<learningSteps.length){const g=learningSteps[demoIndex];if(g.clue?state.evidence.includes(g.clue):state.deductions.includes(g.rule))demoIndex++;else break;}}
 $('demoCoach').hidden=!demoSession;$('missionCard').hidden=!!demoSession;
 const g=currentGoal();
 if(demoSession){$('demoSteps').innerHTML=learningSteps.map((_,i)=>`<span class="${i<demoIndex?'done':i===demoIndex?'current':''}"></span>`).join('');$('demoTitle').textContent=g?g.title:'Training complete';$('demoText').textContent=g?g.text:'You inspected objects, used all three powers and made a valid deduction. Return to your own investigation to finish the remaining connections and choose a suspect.';$('demoAction').textContent=g?(g.obj?'Track objective':'Open evidence board'):'Return to my investigation';}
 else{$('missionTitle').textContent=g?g.title.slice(5):state.deductions.length<3?'Finish the connections':'Name the killer';$('hintText').textContent=g?g.text:state.deductions.length<3?'Connect the service passage with the burned instruction, then the footprint trail with the ledger.':'Review the suspects and use your three deductions to support an accusation.';$('focusGoal').textContent=g?g.button:state.deductions.length<3?'Open evidence board':'Review suspects';}
 if(!demoSession&&difficulty!=='easy'){$('missionTitle').textContent=difficulty==='hard'?'Trust the evidence':'Explore the office';$('hintText').textContent=difficulty==='hard'?'Reconstruct the room, collect evidence, and establish the time, route and identity without hints.':'Explore at your own pace. Request a broad hint if you need a nudge.';$('hint').textContent='Request a hint';}else $('hint').textContent='Explain this step';
 updateTrainingHud(previousDemoIndex);
}
function focusGoal(){if(demoSession){trainingAction();return;}if(!demoSession&&difficulty!=='easy'){hint();return;}const g=currentGoal();if(!g){if(demoSession){exitDemo();return;}if(state.deductions.length<3)board();else suspectPanel(true);return;}if(!g.obj){board();return;}close();stopPlayback();timeConsole=true;state.time=g.time;state.mode=g.mode;targetObject=g.obj;focusedObject=g.obj;Scene3D.setState(state);Scene3D.focus(g.obj);$('cameraView').textContent='First person';render();toast('Click the '+objects.find(o=>o.id===g.obj).label+' label to inspect.');}
function startDemo(){$('levelScreen').hidden=true;if(demoSession){close();return;}close();demoSession={state:JSON.parse(JSON.stringify(state)),timeConsole,wasTitle:$('game').hidden,phase:'preparing',distance:0,activeSeconds:0,assists:0,lastPosition:null,debriefSeen:false};demoIndex=0;stopPlayback();state=fresh();timeConsole=true;started=true;close();$('titleScreen').hidden=true;$('game').hidden=false;Scene3D.reset();render();demoSession.phase='briefing';show('FIELD TRAINING / MISSION BRIEF',`<div class="training-brief"><div class="training-brief-art"><img src="assets/menu-poster.png" alt="The 3D training office"><span>LIVE SIMULATION · CASE 009</span></div><div class="training-brief-copy"><span class="badge">PLAYABLE DEMO</span><h2>Recover the<br>ninth minute.</h2><p>A locked office. A missing key. A clock that cannot be trusted. Learn to reconstruct the scene and prove what really happened.</p><div class="brief-phases"><span><b>01</b> Move & investigate</span><span><b>02</b> Master three powers</span><span><b>03</b> Connect the evidence</span></div><p class="brief-note">Untimed practice. Your saved case stays untouched.</p><button class="primary" data-action="deploy-training">Begin field training →</button><button class="secondary" data-action="exit-training">Exit training</button></div></div>`,true);}
function exitDemo(){if(!demoSession)return;const original=demoSession;demoSession=null;state=original.state;timeConsole=original.timeConsole;demoIndex=0;targetObject=null;stopPlayback();close();Scene3D.reset();$('titleScreen').hidden=!original.wasTitle;$('game').hidden=original.wasTitle;render();toast('Your investigation restored. Practice progress was kept separate.');}
function updateTargetLabel(){const b=$('targetLabel'),p=targetObject?scenePositions[targetObject]:null;if(!p||p.x<4||p.x>96||p.y<8||p.y>88){b.hidden=true;return;}b.hidden=false;b.textContent='Inspect '+objects.find(o=>o.id===targetObject).label;b.style.left=p.x+'%';b.style.top=p.y+'%';}
$('startDemo').onclick=startDemo;$('demoButton').onclick=startDemo;$('demoAction').onclick=trainingAction;$('demoAssist').onclick=trainingAssist;$('exitDemo').onclick=exitDemo;$('focusGoal').onclick=focusGoal;$('targetLabel').onclick=()=>{if(targetObject)inspect(targetObject);};$('resetView').onclick=()=>{targetObject=null;Scene3D.reset();$('cameraView').textContent='First person';updateTargetLabel();};
const objectIcons={window:'▥',door:'▯',clock:'◷',shelf:'▤',desk:'▰',receipt:'▧',key:'⚿',body:'◉',fireplace:'♨',ledger:'▣',trail:'⋮'};
function inspectRoom(){show('ROOM INSPECTION',`<h2>Where will you look?</h2><p>Choose an object to inspect. Collected clues are marked with a check.</p><div class="inspect-grid">${objects.filter(o=>o.id!=='trail'||(state.mode==='shadow'&&state.time===2)).map(o=>{const clue=available(state,o.id);return `<button class="inspect-tile" data-inspect="${o.id}"><span class="object-art ${o.id}">${GameArt.svg(o.id)}</span><span><b>${o.label}</b><small>${clue&&state.evidence.includes(clue)?'✓ Collected':clue&&(difficulty==='easy'||demoSession)?'Evidence available':'Take a closer look'}</small></span></button>`}).join('')}</div>`);}
$('inspectRoom').onclick=inspectRoom;
function sceneObjectAt(e){const r=$('worldCanvas').getBoundingClientRect();const x=e.clientX-(r.left||0),y=e.clientY-(r.top||0);let chosen=null,nearest=46;for(const o of objects){if(o.id==='trail'&&!(state.mode==='shadow'&&state.time===2))continue;const p=scenePositions[o.id];if(!p)continue;const distance=Math.hypot(x-p.x*r.width/100,y-p.y*r.height/100);if(distance<nearest){nearest=distance;chosen=o.id;}}return chosen;}
$('worldCanvas').addEventListener('pointerdown',e=>{pointerStart=[e.clientX,e.clientY];});
$('worldCanvas').addEventListener('pointerup',e=>{if(pointerStart&&Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])<5&&!$('modal').open){const id=sceneObjectAt(e);if(id)inspect(id);}pointerStart=null;});
$('worldCanvas').addEventListener('pointercancel',()=>{pointerStart=null;});
$('worldCanvas').addEventListener('pointermove',e=>{if(pointerStart)return;const id=sceneObjectAt(e);$('worldCanvas').style.cursor=id?'pointer':'grab';$('worldCanvas').title=id?'Inspect '+objects.find(o=>o.id===id).label:'Drag to look around';if(id)focusedObject=id;});
function updateTransport(){
$('playTimeline').textContent=playbackWanted?'Pause scene':'Play scene';$('playTimeline').setAttribute('aria-pressed',playbackWanted);$('transportStatus').textContent=`${playbackWanted?'PLAYING':'PAUSED'} · FRAME 0${state.time+1} / 04`;$('rewindStep').disabled=state.time===0;$('nextStep').disabled=state.time===3;
}
function stopPlayback(){playbackWanted=false;elapsed=0;updateTransport();}
function toggleTimeConsole(){timeConsole=!timeConsole;if(!timeConsole)stopPlayback();render();toast(timeConsole?'TIME console online. Select a moment or play the reconstruction.':'TIME console closed. Current moment preserved.');}
function playbackTick(ms){if(!playbackWanted||$('modal').open||$('game').hidden||document.hidden)return;elapsed+=ms;if(elapsed>=2400){elapsed=0;if(state.time<3)setTime(state.time+1);if(state.time===3)stopPlayback();}}
function saveProgress(){if(demoSession)return;try{localStorage.setItem(saveKey(),JSON.stringify({time:state.time,mode:state.mode,evidence:state.evidence,deductions:state.deductions,ending:state.ending}));}catch{}}
function loadProgress(){try{const data=JSON.parse(localStorage.getItem(saveKey()));if(!data)return false;const s=fresh();s.time=Number.isInteger(data.time)&&data.time>=0&&data.time<4?data.time:3;s.mode=['normal','shadow','fire'].includes(data.mode)?data.mode:'normal';s.evidence=[...new Set((Array.isArray(data.evidence)?data.evidence:[]).filter(id=>clues[id]))];s.deductions=rules.filter(r=>Array.isArray(data.deductions)&&data.deductions.includes(r.id)&&r.needs.every(id=>s.evidence.includes(id))).map(r=>r.id);s.ending=data.ending==='solved'&&s.deductions.length===3?'solved':null;state=s;return s.evidence.length>0;}catch{return false;}}
$('playTimeline').onclick=()=>{playbackWanted=!playbackWanted;elapsed=0;if(playbackWanted&&state.time===3)setTime(0);updateTransport();};
$('rewindStep').onclick=()=>{stopPlayback();setTime(Math.max(0,state.time-1));};$('nextStep').onclick=()=>{stopPlayback();setTime(Math.min(3,state.time+1));};
$('cameraView').onclick=()=>{const p=Scene3D.camera();$('cameraView').textContent=p==='third'?'Third person':'First person';};
Scene3D.init($('worldCanvas'),positions=>{scenePositions=positions;updateTargetLabel();const nearby=Scene3D.nearby();$('walkHint').textContent=nearby?'E · Inspect '+objects.find(o=>o.id===nearby).label:'WASD move · Drag look · Shift run · Space jump';$('nearbyInspect').disabled=!nearby;for(const b of $('hotspots').querySelectorAll('[data-object]')){const p=positions[b.dataset.object];if(p){b.style.left=p.x+'%';b.style.top=p.y+'%';b.hidden=p.x<2||p.x>98||p.y<3||p.y>94;}}});
setInterval(()=>{playbackTick(100);trainingTick(.1);},100);
loadProgress();$('start').onclick=openLevels;
requestAnimationFrame(()=>Scene3D.portrait($('titleOperator'),'player'));window.addEventListener('resize',()=>{if(!$('titleScreen').hidden)Scene3D.portrait($('titleOperator'),'player');document.querySelectorAll('canvas[data-portrait]').forEach(c=>Scene3D.portrait(c,c.dataset.portrait));});
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)document.body.classList.add('reduced');render();

document.addEventListener('visibilitychange',()=>{Scene3D.pause(document.hidden||$('modal').open);syncMenuVideo();syncOfficeMusic();});

function inspectNearby(){const id=Scene3D.nearby();if(id)inspect(id);else toast('Walk closer and face an object, or choose Inspect room.');}
$('nearbyInspect').onclick=inspectNearby;
for(const [id,key]of [['moveForward','w'],['moveLeft','a'],['moveBack','s'],['moveRight','d'],['jumpButton',' ']]){const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);Scene3D.control(key,true);});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,()=>Scene3D.control(key,false));}
function syncMenuVideo(){const v=$('menuVideo'),off=menuPaused||document.body.classList.contains('reduced')||document.hidden||$('titleScreen').hidden;document.body.classList.toggle('at-menu',!$('titleScreen').hidden||!$('levelScreen').hidden);if(off){v.pause();$('menuMotion').textContent='Play background';}else{v.muted=true;const playing=v.play();if(playing&&playing.catch)playing.catch(()=>{menuPaused=true;$('menuMotion').textContent='Play background';});$('menuMotion').textContent='Pause background';}}
$('menuMotion').onclick=()=>{if(document.body.classList.contains('reduced')){toast('Turn off Reduce motion in Settings to play the background.');return;}menuPaused=!menuPaused;syncMenuVideo();};

function saveKey(level=difficulty){return level==='easy'?'rewind-tactical-v2':'rewind-tactical-v2-'+level;}
function openLevels(){if(demoSession)exitDemo();saveProgress();stopPlayback();close();$('game').hidden=true;$('titleScreen').hidden=true;$('levelScreen').hidden=false;Scene3D.setActive(false);selectDifficulty(difficulty);syncMenuVideo();$('levelEasy').focus();}
function selectDifficulty(level){if(!['easy','medium','hard'].includes(level))return;selectedDifficulty=level;for(const l of ['easy','medium','hard']){const button=$('level'+l[0].toUpperCase()+l.slice(1));button.classList.toggle('selected',l===level);button.setAttribute('aria-pressed',l===level);let count=0;try{const saved=JSON.parse(localStorage.getItem(saveKey(l))||'null');count=Array.isArray(saved?.evidence)?saved.evidence.filter(id=>clues[id]).length:0;}catch{}$(l+'Save').textContent=count?count+' / 11 clues collected':'New investigation';}$('levelSummary').textContent=level[0].toUpperCase()+level.slice(1)+' selected · '+({easy:'Full guidance',medium:'Hints on request',hard:'No hints'}[level]);$('launchLevel').textContent='ENTER '+level.toUpperCase()+' →';}
function launchDifficulty(){difficulty=selectedDifficulty;state=fresh();const resumed=loadProgress();targetObject=null;timeConsole=true;Scene3D.reset();$('levelScreen').hidden=true;$('titleScreen').hidden=true;$('game').hidden=false;started=true;if(resumed){render();toast(difficulty.toUpperCase()+' investigation restored.');}else begin();}
for(const level of ['easy','medium','hard'])$('level'+level[0].toUpperCase()+level.slice(1)).onclick=()=>selectDifficulty(level);
$('launchLevel').onclick=launchDifficulty;
$('levelBack').onclick=()=>{$('levelScreen').hidden=true;$('titleScreen').hidden=false;syncMenuVideo();syncOfficeMusic();$('start').focus();};

function deployTraining(){if(!demoSession||demoSession.phase!=='briefing')return;demoSession.phase='movement';Scene3D.reset();demoSession.lastPosition=Scene3D.position();render();$('worldCanvas').focus();trainingFlash('SIMULATION ONLINE','Move two metres to calibrate your field gear.');}
function trainingFlash(title,detail){$('missionFlash').innerHTML='<b>'+title+'</b><span>'+detail+'</span>';$('missionFlash').classList.add('show');setTimeout(()=>$('missionFlash').classList.remove('show'),2600);tone(620);}
function trainingTick(dt){if(!demoSession||!['movement','investigation'].includes(demoSession.phase)||$('modal').open||document.hidden||$('game').hidden)return;demoSession.activeSeconds+=dt;const p=Scene3D.position();if(demoSession.phase==='movement'){const prev=demoSession.lastPosition;if(prev){const d=Math.hypot(p.x-prev.x,p.z-prev.z);if(d<.6)demoSession.distance+=d;}demoSession.lastPosition=p;if(demoSession.distance>=2){demoSession.phase='investigation';targetObject='door';trainingFlash('CALIBRATION COMPLETE','Secure the office. Inspect the locked door.');render();}else updateTrainingHud(demoIndex);}const t=Math.floor(demoSession.activeSeconds);$('trainingTime').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function updateTrainingHud(previous){$('trainingHud').hidden=!demoSession;document.body.classList.toggle('demo-running',!!demoSession);if(!demoSession){$('missionFlash').classList.remove('show');return;}const s=demoSession,moving=['preparing','briefing','movement'].includes(s.phase);if(demoIndex>previous){targetObject=learningSteps[demoIndex]?.obj||null;trainingFlash('EVIDENCE SECURED',demoIndex===8?'Your reconstruction is verified.':'Next objective ready.');}if(demoIndex>=learningSteps.length&&!moving)s.phase='complete';const complete=s.phase==='complete';const count=moving?0:1+demoIndex;$('trainingProgress').textContent=Math.min(9,count)+' / 9';$('trainingFill').style.width=(moving?Math.min(1,s.distance/2)/9:count/9)*100+'%';$('trainingPhase').textContent=moving?'01 / FIELD CALIBRATION':complete?'CERTIFICATION COMPLETE':demoIndex<1?'02 / SECURE THE SCENE':demoIndex<3?'03 / RECONSTRUCT TIME':demoIndex<5?'04 / TRACE THE SHADOW':demoIndex<7?'05 / RECOVER THE ASH':'06 / BUILD YOUR THEORY';$('demoAssist').hidden=moving||complete||!learningSteps[demoIndex]?.obj;
 if(moving){$('demoTitle').textContent='Calibrate your movement';$('demoText').textContent='Walk two metres inside the office. Use WASD or the directional controls, and drag the scene to look around.';$('demoAction').textContent='Show movement controls';$('demoChecklist').innerHTML='<div class="check-row"><span>Distance walked</span><b>'+Math.min(2,s.distance).toFixed(1)+' / 2.0 m</b></div><div class="control-keys"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd><span>or touch controls</span></div>';}else if(complete){$('demoTitle').textContent='Training complete';$('demoText').textContent='You have reconstructed the critical minute. Review your field report, then take on the full investigation.';$('demoAction').textContent='View field report';$('demoChecklist').innerHTML='<div class="check-row done">✓ All 9 objectives complete</div>';}else{const g=learningSteps[demoIndex];$('demoChecklist').innerHTML=g.obj?'<div class="check-row '+(state.time===g.time?'done':'')+'"><span>TIME</span><b>'+times[g.time]+'</b></div><div class="check-row '+(state.mode===g.mode?'done':'')+'"><span>VISION</span><b>'+g.mode.toUpperCase()+'</b></div><div class="check-row"><span>TARGET</span><b>'+objects.find(o=>o.id===g.obj).label+'</b></div>':'<div class="check-row"><span>CONNECT</span><b>Key + clock</b></div>';$('demoAction').textContent=g.obj?'Track objective':'Open evidence board';}}
function trainingAction(){if(!demoSession)return;if(demoSession.phase==='complete'){trainingDebrief();return;}if(demoSession.phase==='briefing'){close();return;}if(demoSession.phase==='movement'){toast('Walk with WASD or the on-screen arrows. Drag to look.');$('worldCanvas').focus();return;}const g=learningSteps[demoIndex];if(!g)return;if(!g.obj){board();return;}targetObject=g.obj;focusedObject=g.obj;timeConsole=true;render();$('worldCanvas').focus();toast(state.time!==g.time?'Use TIME: select '+times[g.time]+'.':state.mode!==g.mode?'Use '+g.mode.toUpperCase()+' vision, then inspect the target.':'Find '+objects.find(o=>o.id===g.obj).label+'. The target is marked when in view.');}
function trainingAssist(){if(!demoSession||demoSession.phase!=='investigation')return;const g=learningSteps[demoIndex];if(!g?.obj)return;demoSession.assists++;targetObject=g.obj;focusedObject=g.obj;Scene3D.focus(g.obj);render();toast('Position assist used. Set the required time and vision yourself.');}
function trainingDebrief(){if(!demoSession||demoSession.phase!=='complete')return;demoSession.debriefSeen=true;const t=Math.floor(demoSession.activeSeconds);show('FIELD REPORT / TRAINING COMPLETE',`<div class="training-results"><div class="certification-mark">✓</div><div class="eyebrow">FIELD CERTIFICATION PASSED</div><h2>The room gave up its first secret.</h2><p>You proved the critical minute using evidence. The full case still needs an escape route and a suspect.</p><div class="result-grid"><div><b>9 / 9</b><span>Objectives complete</span></div><div><b>${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}</b><span>Active practice time</span></div><div><b>${demoSession.assists}</b><span>Position assists</span></div></div><button class="primary" data-action="exit-training">${demoSession.wasTitle?'Return to Gaming Hub':'Return to my investigation'} →</button></div>`,true);}

function syncOfficeMusic(){const music=$('officeMusic');music.volume=.3;if(!soundOn||$('game').hidden||$('modal').open||document.hidden){music.pause();return;}const playing=music.play();if(playing?.catch)playing.catch(()=>{});}
